const items = $input.all();

const seenStudentIds = new Set();
const seenNames = new Set();

const results = [];

// Get today's date in India (YYYY-MM-DD).
function getTodayIST() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Kolkata',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());

  const values = {};

  for (const part of parts) {
    if (part.type !== 'literal') {
      values[part.type] = part.value;
    }
  }

  return `${values.year}-${values.month}-${values.day}`;
}

const todayIST = getTodayIST();

// Convert null, undefined, and other values to trimmed text.
function text(value) {
  return value === null || value === undefined
    ? ''
    : String(value).trim();
}

// Convert names and text fields to proper case.
// Examples: MANOJ K -> Manoj K, chennai -> Chennai.
function properCase(value) {
  return text(value)
    .toLowerCase()
    .replace(/(^|[\s'-])([a-z])/g, (_, separator, letter) =>
      separator + letter.toUpperCase()
    );
}

// Validate a real date and normalize it to YYYY-MM-DD.
// Accepted input formats: DD-MM-YYYY and YYYY-MM-DD.
function normalizeDate(value) {
  const date = text(value);

  let year;
  let month;
  let day;

  let match = date.match(/^(\d{2})-(\d{2})-(\d{4})$/);

  if (match) {
    [, day, month, year] = match;
  } else {
    match = date.match(/^(\d{4})-(\d{2})-(\d{2})$/);

    if (!match) {
      return '';
    }

    [, year, month, day] = match;
  }

  const y = Number(year);
  const m = Number(month);
  const d = Number(day);

  // Reject impossible calendar dates.
  const parsed = new Date(Date.UTC(y, m - 1, d));

  if (
    parsed.getUTCFullYear() !== y ||
    parsed.getUTCMonth() !== m - 1 ||
    parsed.getUTCDate() !== d
  ) {
    return '';
  }

  // Always return YYYY-MM-DD.
  return `${year}-${month}-${day}`;
}

for (const item of items) {
  const row = { ...item.json };

  // Skip completely empty rows.
  if (Object.values(row).every(value => text(value) === '')) {
    continue;
  }

  const errors = [];

  // Clean and normalize values.
  row.Student_ID = text(row.Student_ID);
  row.Name = properCase(row.Name);
  row.Email = text(row.Email).toLowerCase();
  row.Phone = text(row.Phone);
  row.Course = properCase(row.Course);
  row.City = properCase(row.City);
  row.Fee_Paid = text(row.Fee_Paid).toUpperCase();

  const originalDate = text(row.Enrolled_Date);
  const normalizedDate = normalizeDate(originalDate);

  // 1. Student ID: required and unique.
  const studentIdKey = row.Student_ID.toUpperCase();

  if (!row.Student_ID) {
    errors.push('Student ID is missing');
  } else if (seenStudentIds.has(studentIdKey)) {
    errors.push('Duplicate Student ID');
  } else {
    seenStudentIds.add(studentIdKey);
  }

  // 2. Student name: required and unique by the agreed rule.
  const nameKey = row.Name.toLowerCase().replace(/\s+/g, ' ');

  if (!row.Name) {
    errors.push('Student name is missing');
  } else if (seenNames.has(nameKey)) {
    errors.push('Duplicate student name');
  } else {
    seenNames.add(nameKey);
  }

  // 3. Email: required; duplicate email addresses are allowed.
  if (!row.Email) {
    errors.push('Email is missing');
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row.Email)) {
    errors.push(
      'Invalid email format; enter a valid email address'
    );
  }

  // 4. Phone: required and exactly 10 digits.
  // Duplicate phone numbers are allowed.
  if (!row.Phone) {
    errors.push('Phone number is missing');
  } else if (!/^\d{10}$/.test(row.Phone)) {
    errors.push(
      'Invalid phone number; enter exactly 10 digits'
    );
  }

  // 5. Course: required.
  if (!row.Course) {
    errors.push('Course is missing; select a course');
  }

  // 6. Fee status: YES and NO are both valid.
  if (!row.Fee_Paid) {
    errors.push(
      'Fee payment status is missing; enter YES or NO'
    );
  } else if (!['YES', 'NO'].includes(row.Fee_Paid)) {
    errors.push('Invalid fee status; enter YES or NO');
  }

  // 7. City: required.
  if (!row.City) {
    errors.push('City is missing');
  }

  // 8. Enrollment date: required, valid, normalized, and not future.
  if (!originalDate) {
    errors.push('Enrollment date is missing');
  } else if (!normalizedDate) {
    errors.push(
      'Invalid enrollment date; use DD-MM-YYYY or YYYY-MM-DD'
    );
  } else {
    // Save the normalized date even if it is in the future.
    // This allows the invalid CSV to show the standardized date too.
    row.Enrolled_Date = normalizedDate;

    if (normalizedDate > todayIST) {
      errors.push('Enrollment date cannot be in the future');
    }
  }

  // Final validation result.
  row.Validation_Status = errors.length === 0 ? 'Valid' : 'Invalid';
  row.Validation_Errors = errors.join('; ');

  results.push({ json: row });
}

return results;
